
'use strict';

let S,M,dataPath='',wanted=0,saved=0,writing=false,saveTimer=null,saveError='',ui={studyStep:0,exercise:0};
const cats=['RN','EC','SPS','IGV','OGE','MR'];
const names={RN:'Содержание повседневной нормальности',EC:'Обобщённый эпистемический цинизм',SPS:'Текстовое подчёркивание государственной силы',IGV:'Утверждение ценности своей группы',OGE:'Конструирование другой группы как врага',MR:'Особая возвышенная миссия'};
const demoCases=[{case_id:'ДЕМО_1',title:'Искусственный текст для знакомства с программой',current:'Это искусственный учебный абзац для проверки кнопок. Он не является материалом РИА Новости. Здесь можно потренироваться выделять и сохранять точную цитату.',previous:'Искусственный предыдущий абзац: он служит только контекстом.',next:'Искусственный следующий абзац: он тоже не относится к корпусу.',metadata:'Демонстрация интерфейса. Правильные содержательные коды здесь не оцениваются.'},{case_id:'ДЕМО_2',title:'Ещё один искусственный пример интерфейса',current:'Второй искусственный абзац нужен только для проверки перехода и сохранения. Он не входит в исследование.',previous:'',next:'',metadata:'Демонстрация; не независимое наблюдение.'}];
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function md(text){let out='',table=false,list=false;for(let line of String(text).split(/\r?\n/)){if(line.startsWith('|')){if(!line.replace(/[|\-: ]/g,''))continue;if(!table){out+='<table>';table=true}out+='<tr>'+line.replace(/^\||\|$/g,'').split('|').map(c=>'<td>'+inline(c.trim())+'</td>').join('')+'</tr>';continue}if(table){out+='</table>';table=false}if(!line.startsWith('- ')&&list){out+='</ul>';list=false}if(line.startsWith('- ')){if(!list){out+='<ul>';list=true}out+='<li>'+inline(line.slice(2))+'</li>'}else if(/^#{1,4} /.test(line)){let n=line.indexOf(' ');out+=`<h${n}>${inline(line.slice(n+1))}</h${n}>`}else if(line.trim())out+='<p>'+inline(line)+'</p>'}return out+(table?'</table>':'')+(list?'</ul>':'')}
function alertError(e){showModal('Не удалось выполнить действие','<div class="errorbox">'+esc(e.message||e)+'</div><p>Ваши ответы остаются в окне. Если проблема с сохранением повторяется, нажмите «Резервная копия».</p>')}
function showModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function documentById(id){return M.documents.find(x=>x.id===id)}
function showDoc(id){let d=documentById(id);showModal(d.title,'<div class="reader">'+md(d.text)+'</div>')}
function help(){showModal('Как пользоваться программой','<p>Идите по шагам слева. Программа сама сохраняет изменения на этом компьютере.</p><p><b>Во время кодирования:</b> прочитайте текущий абзац и разрешённый контекст, выберите0,1 или? для каждой переменной. Для 1 добавьте точную цитату, говорящего и подачу; для? — причину.</p><p>Кнопка с названием категории открывает её полный текст из зафиксированного кодбука. Программа не подсказывает содержательный ответ.</p><div class="row"><button onclick="showDoc(\'guide\')">Открыть памятку</button><button onclick="folder(false)">Папка сохранений</button></div><p class="path">'+esc(dataPath)+'</p><p>При повторном запуске продолжите с того же места. Закрывайте через «Закончить сеанс», чтобы дождаться сохранения. Если закрыли только окно, вернуться можно через значок программы рядом с часами.</p>')}
function go(page){S.page=page;change();render();window.scrollTo(0,0)}
function render(){let page=S.page||'home';$('nav').innerHTML=[['home','1. Начало'],['study','2. Обучение'],['exercise','3. Самопроверка'],['coding','4. Кодирование'],['finish','5. Результат']].map(([id,title])=>`<button class="${page===id?'active':''}" onclick="go('${id}')">${title}</button>`).join('')+'<div class="side-note">Работа сохраняется здесь.<br>Ничего не отправляется автоматически.<br><br><button class="small" onclick="go(\'demo\')">Потренироваться с кнопками</button></div>';
 let html=page==='home'?home():page==='study'?study():page==='exercise'?exercise():page==='coding'||page==='demo'?coding(page==='demo'):finish();$('main').innerHTML=html;savedLabel()}
function home(){let pending=S.packet?`Пакет «${esc(S.packet.title||S.packet.packet_id)}» загружен.`:'Рабочий пакет ещё не выдан. Это нормально: сначала подготовка.';return `<h1>Добро пожаловать</h1><p class="muted">Здесь собраны все материалы и ответы. С таблицами работать не придётся.</p><div class="card"><label for="coderId">Ваш идентификатор кодировщика</label><input id="coderId" maxlength="100" value="${esc(S.coderId)}" ${S.locked?'disabled':''} placeholder="Идентификатор, который дал исследователь" oninput="S.coderId=this.value;change()"><p class="tiny muted">Можно использовать условное обозначение. Полное имя не обязательно.</p><div class="row"><button class="primary" onclick="go('study')">Начать подготовку</button><button onclick="go('demo')">Сначала попробовать кнопки</button></div></div><div class="cols"><div class="card"><h2>Пять простых шагов</h2><p>Прочитать правила → разобрать примеры → выполнить упражнения → кодировать по одному абзацу → сохранить итоговый файл.</p><p>Предусмотрен один независимый раунд. Его можно выполнить за несколько сеансов.</p></div><div class="card"><h2>Ваше сохранение</h2><p>${pending}</p>${S.locked?'<p class="notice success">Итоговые ответы сохранены и заблокированы.</p>':''}<button onclick="folder(false)">О локальном сохранении</button><button class="quiet small" onclick="$('restoreFile').click()">Восстановить резервную копию</button><p class="path muted">${esc(dataPath)}</p></div></div><p class="endnote">Зафиксированный инструмент: ${esc(M.instrument_version)}. Программа меняет способ ввода, а не правила.</p>`}
function study(){let steps=[['codebook','Правила кодирования'],['guide','Краткая памятка'],['training','Разобранные примеры']];let i=Math.min(ui.studyStep,2),d=documentById(steps[i][0]);return `<h1>Обучение</h1><p class="muted">Полные утверждённые материалы доступны и во время работы. Не нужно держать всё в памяти.</p><div class="catnav">${steps.map((x,n)=>`<button class="${i===n?'active':''}" onclick="ui.studyStep=${n};render()">${n+1}. ${x[1]}</button>`).join('')}</div><div class="card"><div class="reader document-scroll">${md(d.text)}</div></div><div class="footer-actions"><button onclick="ui.studyStep=Math.max(0,ui.studyStep-1);render()">Назад</button><button class="primary" onclick="studyNext()">${i<2?'Прочитано. Дальше':'Перейти к упражнениям'}</button></div>`}
function studyNext(){S.training.readStep=Math.max(S.training.readStep||0,ui.studyStep+1);change();if(ui.studyStep<2){ui.studyStep++;render()}else go('exercise')}
function exercises(){return M.exercises}
function exercise(){let xs=exercises(),i=Math.min(ui.exercise,xs.length-1),x=xs[i];return `<h1>Самопроверка</h1><p class="muted">Это обучение, а не независимый тест. Ключ выдаст исследователь отдельно после выполнения упражнений.</p><div class="row between"><span>Задание ${i+1} из ${xs.length}</span><button class="small" onclick="showDoc('exercise')">Все задания целиком</button></div><div class="progress"><span style="width:${100*(i+1)/xs.length}%"></span></div><div class="card reader">${md(x.text)}</div><div class="card"><label for="exerciseAnswer">Ваш учебный ответ</label><textarea id="exerciseAnswer" rows="5" placeholder="Код, точная цитата при1, объяснение или вопрос — как указано в задании" oninput="S.training.answers['${x.number}']=this.value;change()">${esc(S.training.answers[x.number]||'')}</textarea><p class="tiny muted">Эти записи сохраняются отдельно и не попадут в независимые результаты.</p></div><div class="footer-actions"><button onclick="ui.exercise=Math.max(0,ui.exercise-1);render()">Предыдущее задание</button><button class="primary" onclick="exerciseNext()">${i+1<xs.length?'Следующее задание':'Упражнения выполнены'}</button></div><div class="card"><h2>После самопроверки</h2><p>Запросите у исследователя отдельный ключ. Не начинайте независимое кодирование до сверки и разрешения на рабочий пакет.</p><button onclick="openKey()">Открыть полученный ключ</button><label class="check"><input type="checkbox" ${S.training.keyAcknowledged?'checked':''} onchange="S.training.keyAcknowledged=this.checked;change()">Я выполнил упражнения и сверил ответы с отдельно полученным ключом.</label><label class="check"><input type="checkbox" ${S.training.accepted?'checked':''} onchange="S.training.accepted=this.checked;change()">Правила и процедура мне понятны; нерешённые вопросы обсуждены до теста. Я принимаю объём150 абзацев и план10–13 часов в несколько сеансов.</label><button class="primary" onclick="go('coding')">Перейти к рабочему пакету</button></div>`}
function exerciseNext(){let xs=exercises();if(ui.exercise+1<xs.length){ui.exercise++;render();window.scrollTo(0,0);return}let empty=xs.find(x=>!(S.training.answers[x.number]||'').trim());if(empty){showModal('Есть незаполненное задание',`<p>В задании${empty.number} ещё нет ответа. Если осталось сомнение, запишите его: не нужно угадывать.</p><button onclick="ui.exercise=${xs.indexOf(empty)};$('modal').close();render()">Вернуться к заданию</button>`);return}S.training.completed=true;change();render();showModal('Самопроверка сохранена','<p>Теперь получите отдельный ключ у исследователя, сверьте ответы и отметьте готовность. Это не второй независимый раунд.</p>')}
function openKey(){if(!S.training.completed){showModal('Сначала упражнения','<p>Завершите собственные учебные ответы. Затем исследователь выдаст отдельный ключ.</p>');return}$('keyFile').click()}
function ready(){return S.coderId.trim()&&S.training.completed&&S.training.keyAcknowledged&&S.training.accepted}
function mode(demo){return demo?S.demo:S.work}
function cases(demo){return demo?demoCases:(S.packet?.cases||[])}
function caseResponses(demo,c){let all=demo?S.demo.responses:S.responses;return all[c.case_id]||(all[c.case_id]={})}
function answer(demo,c,cat){let r=caseResponses(demo,c);return r[cat]||(r[cat]={code:'',quotes:[],speaker:'',stance:'',reason:'',note:''})}
function errorFor(a,c){if(!['0','1','?'].includes(a.code))return 'Выберите 0, 1 или ?.';if(a.code==='1'){if(!a.quotes?.length)return 'Для 1 добавьте точную цитату из текущего абзаца.';if(a.quotes.some(q=>!q.trim()||!c.current.includes(q)))return 'Цитата должна точно совпадать с непрерывным фрагментом текущего абзаца.';if(!a.speaker||!a.stance)return 'Для 1 укажите говорящего и подачу.'}if(a.code==='?'&&!a.reason?.trim())return 'Для ? объясните, что именно не удалось разрешить.';return ''}
function complete(demo,c){let r=(demo?S.demo.responses:S.responses)[c.case_id]||{};return cats.every(cat=>r[cat]&&!errorFor(r[cat],c))}
function counts(demo){let cs=cases(demo);return {done:cs.filter(c=>complete(demo,c)).length,total:cs.length}}
function coding(demo){if(!demo&&!S.packet)return `<h1>Рабочий пакет</h1><div class="card"><h2>Пакет пока не загружен</h2><p>Программа не выбирает статьи сама. Исследователь отдельно выдаст разрешённый пакет из150 абзацев разных статей.</p><button class="primary" onclick="$('packetFile').click()">Открыть пакет исследователя</button><button onclick="go('demo')">Попробовать на искусственном тексте</button><p class="tiny muted">Обучение и настоящий раунд сохраняются раздельно. Пустая таблица Excel не является рабочим пакетом.</p></div>`;
 if(!demo&&!ready()&&!S.locked)return `<h1>Перед независимой работой</h1><div class="card"><p>Пакет загружен, но сначала нужны идентификатор кодировщика, выполненные упражнения, сверка с отдельным ключом и принятие процедуры.</p><button class="primary" onclick="go('exercise')">Вернуться к самопроверке</button><button onclick="go('home')">Указать идентификатор</button></div>`;
 let m=mode(demo),cs=cases(demo);m.caseIndex=Math.min(Math.max(0,m.caseIndex),cs.length-1);m.catIndex=Math.min(Math.max(0,m.catIndex),5);let c=cs[m.caseIndex],cat=cats[m.catIndex],a=answer(demo,c,cat),n=counts(demo);ui.currentDemo=demo;ui.currentCase=c;ui.currentCat=cat;
 let option=(values,value)=>'<option value="">Выберите, если можно установить</option>'+values.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
 return `${demo?'<div class="notice demo"><b>ДЕМОНСТРАЦИЯ.</b> Только искусственный текст для кнопок. Правильность кодов здесь не оценивается; ответы не попадут в независимый результат.</div>':''}${S.locked&&!demo?'<div class="notice success">Независимые ответы завершены и заблокированы. Их можно просмотреть и повторно выгрузить.</div>':''}<div class="row between"><h1>${demo?'Попробуйте программу':'Кодирование'}</h1><button class="small" onclick="caseList()">Все случаи</button></div><div class="row between"><span>Случай ${m.caseIndex+1} из ${cs.length}</span><span class="muted">Завершено: ${n.done} из ${n.total}</span></div><div class="progress"><span style="width:${100*n.done/n.total}%"></span></div><div class="card"><div class="eyebrow">Разрешённый контекст</div><details><summary>Заголовок, соседние абзацы и метаданные</summary><b>Заголовок</b><div class="context">${esc(c.title||'[не указан]')}</div><b>Предыдущий абзац</b><div class="context">${esc(c.previous||'[отсутствует]')}</div><b>Следующий абзац</b><div class="context">${esc(c.next||'[отсутствует]')}</div><b>Предоставленные метаданные</b><div class="context">${esc(c.metadata||'[не указаны]')}</div></details><div class="eyebrow">Текущий абзац — доказательство только отсюда</div><div id="currentText" class="current">${esc(c.current)}</div><p class="tiny muted">Контекст помогает толковать. Он не заменяет содержательное доказательство из текущего абзаца.</p></div><div class="card"><div class="row between"><span class="eyebrow">Решение ${m.catIndex+1} из 6</span><div class="catnav">${cats.map((x,i)=>`<button class="${i===m.catIndex?'active':''}" onclick="jumpCat(${i})">${x}${caseResponses(demo,c)[x]&&!errorFor(caseResponses(demo,c)[x],c)?'<span class="dot"></span>':''}</button>`).join('')}</div></div><h2>${cat} — ${names[cat]}</h2><button class="small" onclick="categoryHelp('${cat}')">Открыть точное правило и примеры исключений</button><fieldset ${S.locked&&!demo?'disabled':''}><div class="choices">${[['0','нет признака'],['1','признак есть'],['?','не удаётся решить']].map(([v,t])=>`<button class="choice ${a.code===v?'selected':''}" onclick="choose('${v}')"><strong>${v}</strong> ${t}</button>`).join('')}</div>${a.code==='1'?`<label>Точная цитата из текущего абзаца</label><p class="tiny muted">Выделите слова в текущем абзаце и нажмите кнопку. Несмежные цитаты добавляйте отдельно.</p><button class="small" onmousedown="event.preventDefault()" onclick="selectedQuote()">Добавить выделенный фрагмент</button>${a.quotes.map((q,i)=>`<div class="quote"><span>${esc(q)}</span><button class="small quiet" onclick="removeQuote(${i})">Убрать</button></div>`).join('')}<details><summary>Или вставить цитату вручную</summary><textarea id="quoteDraft" placeholder="Точная цитата без исправлений">${esc(S.drafts?.[draftId()]||'')}</textarea><button class="small" onclick="manualQuote()">Добавить цитату</button></details>`:''}<div class="cols"><div><label for="speaker">Говорящий${a.code==='1'?' — обязателен':''}</label><select id="speaker" onchange="setAnswer('speaker',this.value)">${option(M.speakers,a.speaker)}</select></div><div><label for="stance">Подача${a.code==='1'?' — обязательна':''}</label><select id="stance" onchange="setAnswer('stance',this.value)">${option(M.stances,a.stance)}</select></div></div><p class="tiny muted">Укажите там, где можно установить, в том числе при 0, если атрибуция объясняет исключение. Не выводите её из внешних знаний.</p>${a.code==='?'?`<label for="reason">Что именно осталось неясным?</label><textarea id="reason" oninput="setAnswer('reason',this.value)" placeholder="Конкретная неоднозначность текста или разрешённого контекста">${esc(a.reason)}</textarea>`:''}<details><summary>Необязательное примечание</summary><textarea oninput="setAnswer('note',this.value)">${esc(a.note)}</textarea></details></fieldset><div id="answerWarning" class="inlinewarn" aria-live="polite"></div><div class="footer-actions"><button onclick="move(-1)">Назад</button><div class="row"><button class="quiet" onclick="skip()">Оставить незавершённым</button><button class="primary" onclick="move(1)">${m.catIndex<5?'Дальше':m.caseIndex+1<cs.length?'К следующему абзацу':'К завершению'}</button></div></div></div><details><summary>Идентификаторы и версия источника</summary><p class="path">Случай: ${esc(c.case_id)}<br>Статья: ${esc(c.article_id||'искусственный пример')}<br>Абзац: ${esc(c.paragraph_id||'искусственный пример')}<br>Версия: ${esc(c.source_version||'демонстрация')}</p></details>`}
function currentAnswer(){return answer(ui.currentDemo,ui.currentCase,ui.currentCat)}
function setAnswer(k,v){if(S.locked&&!ui.currentDemo)return;currentAnswer()[k]=v;change()}
function choose(code){setAnswer('code',code);render()}
function draftId(){return (ui.currentDemo?'demo:':'work:')+ui.currentCase.case_id+':'+ui.currentCat}
function addQuote(q){if(!q||!ui.currentCase.current.includes(q)){warning('Выделите непрерывный фрагмент именно текущего абзаца. Текст должен совпадать без исправлений.');return false}let a=currentAnswer();if(!a.quotes.includes(q))a.quotes.push(q);change();render();return true}
function selectedQuote(){let s=window.getSelection(),el=$('currentText');if(!s||!s.rangeCount||!el.contains(s.anchorNode)||!el.contains(s.focusNode)){warning('Выделите слова в области «Текущий абзац», затем нажмите кнопку.');return}addQuote(s.toString())}
function manualQuote(){let q=$('quoteDraft')?.value||'';if(addQuote(q)){if(S.drafts)delete S.drafts[draftId()];change()}}
function removeQuote(i){currentAnswer().quotes.splice(i,1);change();render()}
function warning(t){if($('answerWarning')){$('answerWarning').textContent=t;$('answerWarning').scrollIntoView({block:'nearest'})}}
function jumpCat(i){mode(ui.currentDemo).catIndex=i;change();render()}
function advance(delta){let m=mode(ui.currentDemo),n=cases(ui.currentDemo).length;let at=m.caseIndex*6+m.catIndex+delta;if(at<0){go(ui.currentDemo?'home':'coding');return}if(at>=n*6){go(ui.currentDemo?'home':'finish');return}m.caseIndex=Math.floor(at/6);m.catIndex=at%6;change();render();window.scrollTo(0,0)}
async function move(delta){if(delta>0&&!(S.locked&&!ui.currentDemo)){if(currentAnswer().code==='1'&&$('quoteDraft')?.value&&!currentAnswer().quotes.length){if(!manualQuoteAndKeep())return}let e=errorFor(currentAnswer(),ui.currentCase);if(e){warning(e);return}}try{await flush();advance(delta)}catch(e){alertError(e)}}
function manualQuoteAndKeep(){let q=$('quoteDraft').value;if(!ui.currentCase.current.includes(q)){warning('Вставленная цитата не совпадает с текущим абзацем.');return false}currentAnswer().quotes.push(q);if(S.drafts)delete S.drafts[draftId()];change();return true}
function skip(){advance(1)}
function caseList(){let demo=ui.currentDemo;showModal('Перейти к случаю','<p>Зелёная точка означает, что заполнены все шесть решений. Она не оценивает правильность.</p><div class="case-list">'+cases(demo).map((c,i)=>`<button onclick="mode(${demo}).caseIndex=${i};mode(${demo}).catIndex=0;change();$('modal').close();render()">${i+1}${complete(demo,c)?'<span class="dot"></span>':''}</button>`).join('')+'</div>')}
function categoryHelp(cat){let text=documentById('codebook').text;let rx=new RegExp('^### '+cat+' —[\\s\\S]*?(?=^### |^## |$(?![\\s\\S]))','m');let chunk=text.match(rx)?.[0]||text;showModal(cat+' — точный текст кодбука','<div class="reader">'+md(chunk)+'</div><button onclick="showDoc(\'codebook\')">Открыть кодбук целиком, включая P1–P4</button>')}
function finish(){let n=counts(false);return `<h1>${S.locked?'Итог сохранён':'Сохранить результат'}</h1><div class="card"><h2>${n.done} из ${n.total||150} абзацев завершено</h2><p>Завершение означает наличие всех обязательных полей, а не правильность толкования.</p>${!S.packet?'<p class="notice">Рабочий пакет ещё не загружен. Здесь пока нет независимых ответов.</p>':''}${S.locked?'<p class="notice success">Первоначальные независимые ответы заблокированы. Повторная выгрузка не изменяет их.</p>':'<p>Можно сохранить рабочую копию в любой момент. Итоговый файл создавайте после150 завершённых случаев. После этого независимые ответы блокируются.</p>'}<div class="row"><button onclick="exportResults(false)">Сохранить рабочую копию</button><button class="primary" ${!S.packet||(!S.locked&&n.done!==150)?'disabled':''} onclick="finalize()">${S.locked?'Повторно выгрузить итог':'Завершить и сохранить итог'}</button></div><p id="exportPath" class="path"></p><button class="quiet" onclick="folder(true)">О скачанных файлах</button></div>${S.packet&&n.done<150?'<button onclick="firstPending()">Вернуться к первому незавершённому случаю</button>':''}<div class="card"><h2>Что передать исследователю</h2><p>Программа создаёт ZIP с исходными ответами в JSON, таблицами CSV и SHA-256. Передайте этот файл согласованным способом самостоятельно. Программа ничего не отправляет.</p><p>Демонстрационные и учебные ответы не смешиваются с независимыми результатами.</p></div>`}
function firstPending(){S.work.caseIndex=S.packet.cases.findIndex(c=>!complete(false,c));if(S.work.caseIndex<0)S.work.caseIndex=0;let c=S.packet.cases[S.work.caseIndex],r=S.responses[c.case_id]||{};S.work.catIndex=cats.findIndex(cat=>!r[cat]||errorFor(r[cat],c));if(S.work.catIndex<0)S.work.catIndex=0;go('coding')}
function finalize(){if(S.locked){exportResults(true);return}showModal('Завершить независимую работу?','<p>После сохранения итогового файла первоначальные независимые ответы нельзя будет изменять в программе. Обсуждение расхождений проводится отдельно.</p><button class="primary" onclick="$(\'modal\').close();exportResults(true)">Завершить и сохранить</button>')}
$('keyFile').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Файл ключа слишком большой.');let raw=await f.text(),text=raw;if(/\.html?$/i.test(f.name)){let doc=new DOMParser().parseFromString(raw,'text/html');text=[...doc.body.querySelectorAll('h1,h2,h3,p,li')].map(x=>x.textContent).join('\n\n')}showModal('Отдельно полученный учебный ключ','<div class="plain">'+esc(text)+'</div><p>После сверки закройте ключ и отметьте выполнение. Содержимое ключа не сохраняется в независимые ответы.</p>')}catch(ex){alertError(ex)}finally{e.target.value=''}};
document.addEventListener('input',e=>{if(e.target.id==='quoteDraft'){S.drafts||={};S.drafts[draftId()]=e.target.value;change()}});
window.addEventListener('beforeunload',e=>{if(saved<wanted){e.preventDefault();e.returnValue='Есть несохранённые изменения.'}});
async function init(){await browserInit()}
/* Plain-language accompaniment. Frozen scientific documents are not edited. */
const plainGuide={
 RN:{title:'Обычная жизнь',question:'Здесь содержательно рассказывают об обычной жизни или её продолжении?',look:'Это могут быть повседневные услуги, работа предприятий, покупки, культура или обычные церемонии. Соседнее упоминание кризиса не обязательно.',limit:'Сухое сообщение о болезни, гибели, насилии или военной чрезвычайной ситуации само по себе не становится рассказом об обычной жизни. Случайного слова о нормальности недостаточно.'},
 EC:{title:'Можно ли вообще узнать правду?',question:'Здесь в целом отрицают возможность узнать правду или доверять публичной информации?',look:'Нужно явное обобщение: истину установить невозможно; все стороны лгут; журналистика или институты по природе фальшивы; публичная информация — только манипуляция.',limit:'Обвинения одного человека, одного СМИ или одного события недостаточно. Сам спор с конкретным сообщением ещё не означает этот признак.'},
 SPS:{title:'Возможности и сила государства',question:'Здесь специально подчёркивают государственную силу, контроль или возможность принуждения?',look:'Ищите выраженный акцент на государственном охвате, контроле, исполнении, наказании, наблюдении, блокировках или неотвратимости государственного действия. Подчёркнутая суровость возможного наказания тоже может учитываться.',limit:'Обычная работа учреждения или успешная военная операция сами по себе недостаточны. Угроза наказания не означает, что его уже исполнили.'},
 IGV:{title:'Ценность своей группы',question:'Здесь прямо подчёркивают коллективную или моральную ценность России либо понятной из текста союзной группы?',look:'Например, прямо утверждают её единство, стойкость, верность, достоинство, героизм или жертвенность. Важна связь с общей идентичностью группы.',limit:'Одного спортивного результата, объёма помощи или экономического успеха недостаточно. Если нужная принадлежность просто не указана — это 0; если сама атрибуция действительно неразрешима — можно ? с причиной.'},
 OGE:{title:'Изображение другой группы как врага',question:'Здесь понятную из текста другую группу изображают моральным врагом или угрозой?',look:'Это может быть враждебная характеристика — например, преступники или террористы. Либо прямо описанная намеренная тяжёлая жестокость, которая сама создаёт образ моральной угрозы.',limit:'Одного сообщения об обстреле, жертвах или повреждении здания недостаточно. Не выводите намеренную жестокость только из причинённого вреда.'},
 MR:{title:'Особая возвышенная миссия',question:'Здесь России или понятной из текста союзной группе приписывают особую возвышенную роль?',look:'Ищите явную особую моральную, историческую, цивилизационную, спасительную или священную роль — сверх обычной обороны и интересов.',limit:'Обычной защиты, безопасности или помощи людям недостаточно, даже если говорится о защите от геноцида. Слова «миссия» или «историческая справедливость» сами по себе не заменяют весь критерий.'}
};
const reasonChoices=['Неясно, кто произносит нужное утверждение','Неясно, к кому относится утверждение или какая группа имеется в виду','Неясно, принимает ли текст чужое утверждение или дистанцируется от него','Разрешённого соседнего контекста недостаточно для толкования','Неоднозначно, выполнен ли сам критерий в этом тексте','Другая конкретная причина'];
const speakerLabels=['Автор самого текста','Российский чиновник / государственный источник','Пророссийский негосударственный источник','Украинский / западный / противостоящий источник','Другой сторонний источник','Не удалось установить'];
const stanceLabels=['В тексте явно поддерживают или принимают утверждение','Приводят без явного оспаривания','Опровергают или отстраняются от него','Нейтрально передают','Не удалось установить'];
const rule8Options=['Достаточно обвинения одного конкретного СМИ во лжи','Нужно явное обобщённое утверждение о правде или публичной информации','Достаточно любого несогласия с сообщением'];
const rule9Questions=['Защита от геноцида автоматически означает MR=1?','Сторонний говорящий автоматически исключает RN?','Ущерба гражданскому объекту достаточно для OGE?','Успешного огня военных достаточно для SPS?','Один положительный код автоматически переносится на остальные?'];
function guideCard(cat){let g=plainGuide[cat];return `<h2>${g.question}</h2><p>${g.look}</p><div class="plain-boundary"><b>Граница:</b> ${g.limit}</div><button class="quiet small" onclick="categoryHelp('${cat}')">Полное правило ${cat}</button>`}
function statusChips(selected,handler){return `<div class="choices">${[['1','Да','Записать 1'],['0','Нет','Записать 0'],['?','Пока не могу решить','Записать ?']].map(([v,t,h])=>`<button class="choice ${selected===v?'selected':''}" onclick="${handler}('${v}')"><b>${t}</b><small>${h}</small></button>`).join('')}</div>`}
function home(){let resume=S.packet?'Продолжить работу':'Начать знакомство';return `<div class="welcome"><div class="eyebrow">Всё по шагам</div><h1>Ваша задача — читать и отмечать</h1><p class="lead">Вы будете читать короткие фрагменты новостей. Для каждого программа по очереди спросит о шести признаках.</p><div class="card"><h2>Сначала покажем, как это делать</h2><ol class="simple-list"><li>Коротко объясним каждый признак.</li><li>Покажем разобранные примеры.</li><li>Предложим учебные задания.</li><li>После подготовки откроем отдельно выданную работу.</li></ol><p>Не нужно писать сочинение. Обычно достаточно выбрать кнопку. Иногда потребуется выделить слова из текста.</p><button class="primary" onclick="go('${S.packet?'coding':'study'}')">${resume}</button><button class="quiet" onclick="go('demo')">Сразу попробовать кнопки</button></div><details><summary>Как вас обозначить в результатах?</summary><label for="coderId">Обозначение, которое дал исследователь</label><input id="coderId" maxlength="100" value="${esc(S.coderId)}" ${S.locked?'disabled':''} placeholder="Например, Кодер2" oninput="S.coderId=this.value;change()"><p class="tiny muted">Полное имя не обязательно. Это понадобится перед настоящей работой.</p></details><div class="notice success">Ответы сохраняются автоматически. Можно делать перерывы и продолжать с того же места.</div><details><summary>Мои файлы и резервные копии</summary><button onclick="folder(false)">О локальном сохранении</button><button onclick="$('restoreFile').click()">Восстановить копию</button><p class="path">${esc(dataPath)}</p></details></div>`}
function lessons(){return ['intro',...cats,'voices']}
function study(){let ls=lessons(),i=Math.min(S.training.lessonIndex||0,ls.length-1),key=ls[i];let body;
 if(S.training.studyPart==='examples')return exampleStudy();
 if(key==='intro')body=`<h2>Что от вас требуется</h2><p class="lead">Замечать, <b>как написан текст</b>. Не нужно проверять новости на правдивость или угадывать мысли журналиста.</p><div class="walk-row"><b>1. Прочитайте выделенный абзац.</b><p>При необходимости откройте заголовок и два соседних абзаца. Другие новости искать не нужно. Соседние абзацы помогают понять смысл, но подтверждающие слова должны быть в текущем абзаце.</p></div><div class="walk-row"><b>2. Ответьте на вопрос программы.</b><p>«Да» означает, что нужный признак есть. «Нет» — что его нет. «Пока не могу решить» — что осталась настоящая неоднозначность.</p></div><div class="walk-row"><b>3. Покажите слова, если выбрали «Да».</b><p>Их можно выделить мышью и добавить одной кнопкой. Самостоятельно переписывать цитату не нужно.</p></div><p>Дальше познакомимся с шестью признаками по одному.</p>`;
 else if(key==='voices')body=`<h2>Ещё два коротких уточнения</h2><p>Программа спросит, <b>кто говорит</b> и <b>как подано утверждение</b>. Здесь тоже будет выбор из готовых вариантов.</p><p>Для EC, SPS, IGV, OGE и MR действуют общие правила:<ul><li>Слова самого повествователя оценивайте по содержанию.</li><li>Слова российского официального или явно пророссийского источника могут учитываться, если текст их явно не опровергает и не отстраняется от них.</li><li>Для украинского, западного, противостоящего или другого стороннего источника одной цитаты недостаточно: нужна явная местная поддержка, принятие или содержательное воспроизведение механизма текстом РИА.</li><li>Явно опровергнутые или дистанцированные утверждения не дают положительного кода.</li></ul>Принадлежность определяйте только по разрешённому тексту, без догадок по национальности. Если она действительно неразрешима, оставьте ? с причиной.</p><div class="notice">Для RN есть отдельное исключение: сторонняя цитата может содержать обычное функционирование и без поддержки РИА, если контекст не подрывает его и не превращает в прямой кризисный сюжет.</div><p>Все шесть признаков проверяются отдельно. В одном абзаце могут встречаться несколько.</p><button class="quiet" onclick="showDoc('codebook')">Открыть полный кодбук</button>`;
 else body=`<div class="eyebrow">${key} · ${plainGuide[key].title}</div>${guideCard(key)}<p class="muted">Пока ничего кодировать не нужно. Далее будут реальные разобранные учебные примеры.</p>`;
 return `<h1>Разберёмся вместе</h1><p class="muted">Шаг ${i+1} из ${ls.length}. Полные правила всегда можно открыть отдельно.</p><div class="progress"><span style="width:${100*(i+1)/ls.length}%"></span></div><div class="card coaching">${body}</div><div class="footer-actions"><button onclick="lessonBack()" ${i===0?'disabled':''}>Назад</button><button class="primary" onclick="studyNext()">${i===ls.length-1?'Теперь посмотреть примеры':'Понятно, дальше'}</button></div>`}
function lessonBack(){S.training.lessonIndex=Math.max(0,(S.training.lessonIndex||0)-1);change();render()}
function studyNext(){let i=S.training.lessonIndex||0;if(i+1<lessons().length)S.training.lessonIndex=i+1;else{S.training.studyPart='examples';S.training.exampleIndex??=0}change();render();window.scrollTo(0,0)}
function exampleStudy(){let xs=M.trainingCards||[],i=Math.min(S.training.exampleIndex||0,xs.length-1),x=xs[i];return `<h1>Посмотрим на примерах</h1><p class="muted">Пример ${i+1} из ${xs.length}. Это обучение: решение и объяснение уже показаны.</p><div class="progress"><span style="width:${100*(i+1)/xs.length}%"></span></div><div class="card reader">${compactSource(x.text,true)}</div><div class="footer-actions"><button onclick="exampleBack()">Назад</button><button class="primary" onclick="exampleNext()">${i+1===xs.length?'Теперь попробовать самостоятельно':'Следующий пример'}</button></div><button class="quiet small" onclick="showDoc('training')">Все утверждённые примеры целиком</button>`}
function exampleBack(){if((S.training.exampleIndex||0)>0)S.training.exampleIndex--;else{S.training.studyPart='lessons';S.training.lessonIndex=lessons().length-1}change();render()}
function exampleNext(){if((S.training.exampleIndex||0)+1<(M.trainingCards||[]).length){S.training.exampleIndex++;change();render();window.scrollTo(0,0)}else go('exercise')}
function fieldFrom(text,label){let rx=new RegExp('^\\*\\*'+label.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+':\\*\\* ([\\s\\S]*?)(?=\\r?\\n\\r?\\n|$(?![\\s\\S]))','m');return text.match(rx)?.[1]||''}
function compactSource(text,answered){let current=fieldFrom(text,'Текущий абзац');if(!current)return md(text);let title=fieldFrom(text,'Заголовок'),prev=fieldFrom(text,'Предыдущий абзац'),next=fieldFrom(text,'Следующий абзац');let parts=String(text).split(/\r?\n\r?\n/);let result=parts.filter(p=>p.startsWith('**Утверждено')||p.startsWith('**Учебная пригодность')||p.startsWith('**Объяснение')||p.startsWith('**Оговорки и объяснение')||p.startsWith('**Рассматриваемый фрагмент')||p.startsWith('**Точное доказательство')||p.startsWith('**Говорящий / подача'));
 return `${title?'<p><b>Заголовок:</b> '+esc(title)+'</p>':''}<div class="eyebrow">Текущий абзац</div><div class="current ${answered?'':'exercise-current'}" ${answered?'':'id="exerciseText"'}>${esc(current)}</div><details><summary>Нужен соседний контекст?</summary><div class="context">${esc(prev||'[отсутствует]')}</div><div class="context">${esc(next||'[отсутствует]')}</div></details>${answered?'<div class="notice">'+result.map(md).join('')+'</div>':''}<details><summary>Исходный учебный материал и данные источника</summary>${md(text)}</details>`}
function exerciseEntry(number){let old=S.training.answers[number];if(old&&typeof old==='object')return old;return {kind:'choice',code:'',quotes:[],speaker:'',stance:'',reason:'',note:'',legacyText:typeof old==='string'?old:''}}
function storeExercise(a){let x=exercises()[ui.exercise];S.training.answers[x.number]=a;change()}
function exerciseCase(x){let current=fieldFrom(x.text,'Текущий абзац');if(!current&&x.number==='10')current=M.syntheticExerciseText;return {current:current||'',case_id:'TRAINING_'+x.number}}
function exerciseValid(x){let raw=S.training.answers[x.number];if(typeof raw==='string')return raw.trim()? '':'Выберите ответ.';let a=exerciseEntry(x.number);if(x.number==='8')return a.selectedOption?'':'Выберите один вариант.';if(x.number==='9')return rule9Questions.every((_,i)=>['Да','Нет'].includes(a.subchoices?.[i]))?'':'Ответьте на каждый короткий вопрос.';return errorFor(a,exerciseCase(x))}
function exercise(){let xs=exercises(),i=Math.min(ui.exercise,xs.length-1),x=xs[i],a=exerciseEntry(x.number),concept=['8','9'].includes(x.number);let question;
 if(x.number==='8')question=`<div class="card"><h2>Достаточно ли для EC обвинения одного СМИ во лжи?</h2><p>Выберите, какой ответ соответствует правилу. Программа не оценивает его автоматически.</p>${rule8Options.map((label,n)=>`<button class="answer-option ${a.selectedOption===String(n+1)?'selected':''}" onclick="chooseRule8(${n})">${esc(label)}</button>`).join('')}</div>`;
 else if(x.number==='9')question=`<div class="card"><h2>Пять коротких вопросов</h2>${rule9Questions.map((q,n)=>`<div class="mini-question"><p>${q}</p><div class="row">${['Да','Нет'].map(v=>`<button class="${a.subchoices?.[n]===v?'selected':''}" onclick="chooseRule9(${n},'${v}')">${v}</button>`).join('')}</div></div>`).join('')}</div>`;
 else{let cat=x.category||x.text.match(/### (RN|EC|SPS|IGV|OGE|MR)/)?.[1]||'EC';let c=exerciseCase(x);question=`<div class="card">${x.number==='10'?'<div class="notice demo"><b>Искусственный учебный пример, не цитата РИА и не исследовательская статья.</b></div><div class="current" id="exerciseText">'+esc(c.current)+'</div><p>Учебное условие: допустимый голос повествователя, без опровержения.</p><details><summary>Полный текст учебного условия</summary>'+md(x.text)+'</details>':compactSource(x.text,false)}</div><div class="card"><div class="eyebrow">${cat} · ${plainGuide[cat].title}</div><h2>${plainGuide[cat].question}</h2><button class="quiet small" onclick="categoryHelp('${cat}')">Полное правило</button>${statusChips(a.code,'chooseExercise')}${a.code==='1'?trainingEvidence(a):a.code==='?'?reasonUI(a,true):''}${a.code?attributionUI(a,true):''}</div>`}
 return `<h1>Теперь попробуйте сами</h1><p class="muted">Учебное задание ${i+1} из ${xs.length}. Здесь можно выбирать кнопками. Правильные ответы сверим позже по отдельно выданному ключу.</p><div class="progress"><span style="width:${100*(i+1)/xs.length}%"></span></div>${a.legacyText?'<details><summary>Ваш ранее написанный ответ сохранён</summary><p class="plain">'+esc(a.legacyText)+'</p></details>':''}${question}<div class="card"><label>Ваши наблюдения — желательно, если есть что пояснить</label><textarea placeholder="Одной короткой фразы достаточно. Можно оставить пустым." oninput="exerciseNote(this.value)">${esc(a.note||'')}</textarea><p class="tiny muted">Не нужно заново пересказывать весь текст или правило.</p><div id="exerciseWarning" class="inlinewarn"></div></div><div class="footer-actions"><button onclick="ui.exercise=Math.max(0,ui.exercise-1);render()">Назад</button><button class="primary" onclick="exerciseNext()">${i+1<xs.length?'Сохранить и дальше':'Я выполнил упражнения'}</button></div>${i===xs.length-1?trainingFinish():''}`}
function chooseExercise(code){let a=exerciseEntry(exercises()[ui.exercise].number);a.code=code;storeExercise(a);render()}
function chooseRule8(n){let a=exerciseEntry('8');a.kind='rule-choice';a.selectedOption=String(n+1);a.selectedText=rule8Options[n];storeExercise(a);render()}
function chooseRule9(n,v){let a=exerciseEntry('9');a.kind='rule-questions';a.subchoices??={};a.subchoices[n]=v;storeExercise(a);render()}
function exerciseNote(v){let a=exerciseEntry(exercises()[ui.exercise].number);a.note=v;storeExercise(a)}
function trainingEvidence(a){return `<label>Какие слова показывают признак?</label><p>Выделите их мышью в текущем абзаце. Потом нажмите кнопку ниже.</p><button onmousedown="event.preventDefault()" onclick="trainingSelection()">Взять выделенные слова</button>${(a.quotes||[]).map(q=>'<div class="quote">'+esc(q)+'</div>').join('')}<details><summary>Вставить точную цитату вручную</summary><textarea id="trainingQuote" placeholder="Цитата без исправлений"></textarea><button onclick="trainingManualQuote()">Добавить цитату</button></details>`}
function trainingAdd(q){let x=exercises()[ui.exercise],c=exerciseCase(x);if(!q?.trim()||!c.current.includes(q)){showModal('Возьмите слова из текущего абзаца','<p>Цитата должна точно совпадать с выделенным фрагментом. Не исправляйте её и не добавляйте слова от себя.</p>');return}let a=exerciseEntry(x.number);a.quotes??=[];if(!a.quotes.includes(q))a.quotes.push(q);storeExercise(a);render()}
function trainingSelection(){let s=window.getSelection(),el=$('exerciseText');if(!s||!el?.contains(s.anchorNode)||!el.contains(s.focusNode)){showModal('Выделите слова в абзаце','<p>Сначала выделите мышью нужный фрагмент в блоке «Текущий абзац».</p>');return}trainingAdd(s.toString())}
function trainingManualQuote(){trainingAdd($('trainingQuote').value)}
function attributionUI(a,training){let set=training?'setTrainingField':'setAnswer';return `<div class="cols"><div><label>Кто произносит утверждение для этой категории?</label><select aria-label="Кто произносит утверждение" onchange="${set}('speaker',this.value)"><option value="">Выберите вариант</option>${M.speakers.map((v,i)=>`<option value="${esc(v)}" ${a.speaker===v?'selected':''}>${speakerLabels[i]}</option>`).join('')}</select></div><div><label>Как подано утверждение для этой категории?</label><select aria-label="Как утверждение подано" onchange="${set}('stance',this.value)"><option value="">Выберите вариант</option>${M.stances.map((v,i)=>`<option value="${esc(v)}" ${a.stance===v?'selected':''}>${stanceLabels[i]}</option>`).join('')}</select></div></div><p class="tiny muted">Ориентируйтесь только на предоставленный текст. «Не удалось установить» выбирайте сами, если это действительно так. Эти поля сохраняются отдельно для каждого из шести признаков. Для «Да» они обязательны; в остальных случаях указывайте, где можете.</p>`}
function setTrainingField(k,v){let a=exerciseEntry(exercises()[ui.exercise].number);a[k]=v;storeExercise(a)}
function reasonUI(a,training){let action=training?'chooseTrainingReason':'chooseReason';return `<h3>Что именно осталось неясным?</h3><p>Можно выбрать готовую причину. Если она не подходит, укажите другую своими словами.</p><div class="reason-grid">${reasonChoices.map((v,i)=>`<button class="answer-option ${a.reasonChoice===v?'selected':''}" onclick="${action}(${i})">${v}</button>`).join('')}</div>${a.reasonChoice===reasonChoices[5]||(!a.reasonChoice&&a.reason)?`<label>Уточните причину</label><textarea aria-label="Уточнение причины" oninput="${training?'trainingReasonDetail':'reasonDetail'}(this.value)" placeholder="Что именно нельзя понять из текста?">${esc(a.reasonDetail||a.reason||'')}</textarea>`:''}<p class="tiny muted">Если нужного признака просто нет, это «Нет». Неопределённость нужна для настоящей неразрешённой неоднозначности.</p>`}
function putReason(a,i){a.reasonChoice=reasonChoices[i];a.reasonDetail='';a.reason=i===5?'':reasonChoices[i]}
function chooseReason(i){let a=currentAnswer();putReason(a,i);change();render()}
function reasonDetail(v){let a=currentAnswer();a.reasonDetail=v;a.reason=v;change()}
function chooseTrainingReason(i){let a=exerciseEntry(exercises()[ui.exercise].number);putReason(a,i);storeExercise(a);render()}
function trainingReasonDetail(v){let a=exerciseEntry(exercises()[ui.exercise].number);a.reasonDetail=v;a.reason=v;storeExercise(a)}
function trainingFinish(){return `<div class="card"><h2>После упражнений</h2><p>Исследователь выдаст ключ отдельно. Сравните с ним свои ответы до настоящего задания.</p><button onclick="openKey()">Открыть полученный ключ</button><label class="check"><input type="checkbox" ${S.training.keyAcknowledged?'checked':''} onchange="S.training.keyAcknowledged=this.checked;change()">Я сверил свои ответы с отдельно полученным ключом.</label><label class="check"><input type="checkbox" ${S.training.accepted?'checked':''} onchange="S.training.accepted=this.checked;change()">Правила понятны, вопросы обсуждены с исследователем. Я принимаю150 абзацев и10–13 часов работы в несколько сеансов.</label><button class="primary" onclick="go('coding')">К настоящему заданию</button></div>`}
function exerciseNext(){let xs=exercises(),x=xs[ui.exercise],err=exerciseValid(x);if(err){$('exerciseWarning').textContent=err;$('exerciseWarning').scrollIntoView({block:'nearest'});return}if(ui.exercise+1<xs.length){ui.exercise++;S.training.exerciseIndex=ui.exercise;change();render();window.scrollTo(0,0);return}let missing=xs.find(y=>exerciseValid(y));if(missing){ui.exercise=xs.indexOf(missing);render();showModal('Осталось незавершённое задание','<p>Закончите выбранный учебный вопрос. Не нужно угадывать: можно отметить настоящую неопределённость с причиной.</p>');return}S.training.completed=true;change();render();showModal('Упражнения сохранены','<p>Теперь получите отдельный ключ у исследователя. После сверки отметьте готовность внизу страницы. Программа не выставляла оценку вашим ответам.</p>')}
function guidedContext(c){return `<details class="context-toggle"><summary>Открыть заголовок и соседние абзацы</summary><b>Заголовок</b><div class="context">${esc(c.title||'[не указан]')}</div><b>Предыдущий абзац</b><div class="context">${esc(c.previous||'[отсутствует]')}</div><b>Следующий абзац</b><div class="context">${esc(c.next||'[отсутствует]')}</div><b>Сведения об авторе и источнике</b><div class="context">${esc(c.metadata||'[не указаны]')}</div></details>`}
function coding(demo){if(!demo&&!S.packet)return `<h1>Настоящее задание будет отдельно</h1><div class="card coaching"><p class="lead">Пока можно спокойно пройти подготовку и попробовать кнопки. Проверочных статей в программе сейчас нет.</p><button class="primary" onclick="go('study')">Пройти подготовку</button><button onclick="go('demo')">Попробовать кнопки</button><details><summary>Исследователь уже выдал мне файл задания</summary><p>Откройте только тот пакет, который отдельно выдал исследователь. Программа сама статьи не ищет.</p><button onclick="$('packetFile').click()">Открыть файл задания</button></details></div>`;
 if(!demo&&!ready()&&!S.locked)return `<h1>Сначала закончим подготовку</h1><div class="card"><p>Перед настоящей работой нужны учебные ответы, сверка с отдельно полученным ключом и согласие с процедурой.</p><button class="primary" onclick="ui.exercise=exercises().length-1;go('exercise')">Вернуться к подготовке</button><button onclick="go('home')">Указать обозначение кодировщика</button></div>`;
 let m=mode(demo),cs=cases(demo);m.caseIndex=Math.min(Math.max(0,m.caseIndex),cs.length-1);m.catIndex=Math.min(Math.max(0,m.catIndex),5);m.flowStep=Math.min(Math.max(0,m.flowStep||0),2);let c=cs[m.caseIndex],cat=cats[m.catIndex],a=answer(demo,c,cat),n=counts(demo),g=plainGuide[cat];ui.currentDemo=demo;ui.currentCase=c;ui.currentCat=cat;let step=m.flowStep,body;
 if(step===0)body=`<div class="eyebrow">Признак ${m.catIndex+1} из6 · ${cat}</div>${guideCard(cat)}${statusChips(a.code,'choose')}<p class="tiny muted">Выбор можно изменить. При «Да» дальше покажем, как взять цитату.</p>`;
 else if(step===1)body=a.code==='1'?`<div class="eyebrow">Вы выбрали «Да» · ${cat}</div><h2>Покажите, какие слова это подтверждают</h2><p>Выделите мышью нужные слова в текущем абзаце и нажмите кнопку. Не нужно печатать их заново.</p><button class="primary" onmousedown="event.preventDefault()" onclick="selectedQuote()">Взять выделенные слова</button>${a.quotes.map((q,i)=>`<div class="quote"><span>${esc(q)}</span><button class="quiet small" onclick="removeQuote(${i})">Убрать</button></div>`).join('')}<details><summary>Вставить цитату вручную</summary><textarea id="quoteDraft" placeholder="Точная цитата без исправлений">${esc(S.drafts?.[draftId()]||'')}</textarea><button onclick="manualQuote()">Добавить цитату</button></details><p class="tiny muted">Берите слова только из текущего абзаца, без исправлений. Несмежные фрагменты добавляйте отдельно.</p>`:`<div class="eyebrow">Вы выбрали «Пока не могу решить» · ${cat}</div>${reasonUI(a,false)}`;
 else body=`<div class="eyebrow">Уточнение к вашему ответу · ${cat}</div><h2>${a.code==='1'?'Осталось выбрать два варианта':'Уточните, если можете установить по тексту'}</h2>${attributionUI(a,false)}<div class="notice">${cat==='RN'?'Для этого признака сторонняя цитата сама по себе не мешает ответить «Да»: проверьте содержание и соседний контекст по правилу RN.':'Не всякая чужая цитата считается признаком. При сомнении откройте полное правило: важны говорящий и то, как текст подаёт утверждение.'}</div><button class="quiet small" onclick="categoryHelp('${cat}')">Полное правило</button><label for="observations">Ваши наблюдения — желательно, если есть что пояснить</label><textarea id="observations" placeholder="Одной короткой фразы достаточно. Можно оставить пустым." oninput="setAnswer('note',this.value)">${esc(a.note)}</textarea><p class="tiny muted">Не нужно пересказывать абзац или писать объяснение «для отчёта».</p>`;
 return `${demo?'<div class="notice demo"><b>Пробуем кнопки.</b> Здесь искусственный текст. Программа не оценивает правильность кодов; эти ответы не попадут в исследование.</div>':''}${S.locked&&!demo?'<div class="notice success">Итог уже сохранён. Ответы доступны только для просмотра.</div>':''}<div class="row between"><h1>${demo?'Потренируемся вместе':'Читаем и отмечаем'}</h1><button class="small" onclick="caseList()">Перейти к другому абзацу</button></div><div class="row between"><span>Абзац ${m.caseIndex+1} из ${cs.length}</span><span class="muted">Готово: ${n.done} из ${n.total}</span></div><div class="progress"><span style="width:${100*n.done/n.total}%"></span></div><div class="card"><div class="eyebrow">Прочитайте этот абзац</div><div id="currentText" class="current">${esc(c.current)}</div>${guidedContext(c)}</div><div class="card coaching"><div class="step-track"><span class="${step===0?'on':''}">1. Выбор</span><span class="${step===1?'on':''}">2. Слова или причина</span><span class="${step===2?'on':''}">3. Уточнение</span></div><fieldset ${S.locked&&!demo?'disabled':''}>${body}</fieldset><div id="answerWarning" class="inlinewarn" aria-live="polite"></div><div class="footer-actions"><button onclick="move(-1)">Назад</button><div class="row"><button class="quiet small" onclick="skip()">Вернуться к этому позже</button>${step!==0||a.code?`<button class="primary" onclick="move(1)">${step===2?(m.catIndex===5?'Сохранить абзац и дальше':'К следующему признаку'):'Продолжить'}</button>`:''}</div></div></div><details><summary>Номер случая и технические сведения</summary><p class="path">${esc(c.case_id)}<br>${esc(c.article_id||'искусственный пример')}<br>${esc(c.paragraph_id||'искусственный пример')}<br>${esc(c.source_version||'демонстрация')}</p></details>`}
function choose(code){if(S.locked&&!ui.currentDemo)return;setAnswer('code',code);mode(ui.currentDemo).flowStep=code==='0'?2:1;change();render();window.scrollTo(0,0)}
function jumpCat(i){let m=mode(ui.currentDemo);m.catIndex=i;m.flowStep=0;change();render()}
function advance(delta){let m=mode(ui.currentDemo),n=cases(ui.currentDemo).length,at=m.caseIndex*6+m.catIndex+delta;if(at<0){go('home');return}if(at>=n*6){go(ui.currentDemo?'home':'finish');return}m.caseIndex=Math.floor(at/6);m.catIndex=at%6;m.flowStep=0;change();render();window.scrollTo(0,0)}
async function move(delta){let m=mode(ui.currentDemo),a=currentAnswer(),c=ui.currentCase;if(delta<0){if(m.flowStep>0){m.flowStep=(m.flowStep===2&&a.code==='0')?0:m.flowStep-1;change();render();return}advance(-1);return}
 if(S.locked&&!ui.currentDemo){advance(1);return}
 if(m.flowStep===0){if(!a.code){warning('Сначала выберите один из трёх вариантов.');return}m.flowStep=a.code==='0'?2:1}
 else if(m.flowStep===1){if(a.code==='1'){if(!a.quotes.length&&$('quoteDraft')?.value&&!manualQuoteAndKeep())return;if(!a.quotes.length||a.quotes.some(q=>!q.trim()||!c.current.includes(q))){warning('Возьмите хотя бы один точный фрагмент из текущего абзаца.');return}}else if(!a.reason.trim()){warning('Выберите готовую причину или кратко напишите свою.');return}m.flowStep=2}
 else{let e=errorFor(a,c);if(e){warning(e);return}try{await flush();advance(1)}catch(e){alertError(e)}return}
 change();render();window.scrollTo(0,0)}
function caseList(){let demo=ui.currentDemo;showModal('К какому абзацу перейти?','<p>Зелёная точка означает только заполненные поля, а не правильность ответа.</p><div class="case-list">'+cases(demo).map((c,i)=>`<button onclick="mode(${demo}).caseIndex=${i};mode(${demo}).catIndex=0;mode(${demo}).flowStep=0;change();$('modal').close();render()">${i+1}${complete(demo,c)?'<span class="dot"></span>':''}</button>`).join('')+'</div>')}
function firstPending(){S.work.caseIndex=S.packet.cases.findIndex(c=>!complete(false,c));if(S.work.caseIndex<0)S.work.caseIndex=0;let c=S.packet.cases[S.work.caseIndex],r=S.responses[c.case_id]||{};S.work.catIndex=cats.findIndex(cat=>!r[cat]||errorFor(r[cat],c));if(S.work.catIndex<0)S.work.catIndex=0;S.work.flowStep=0;go('coding')}
function help(){showModal('Если вы только начали','<h3>Всё делается по очереди</h3><p>Сначала короткое объяснение, затем примеры и учебные задания. Во время настоящей работы программа показывает один абзац и один вопрос.</p><p>Обычно нужно нажать кнопку. Если выбрали «Да» — выделить подтверждающие слова. Если осталась настоящая неясность — выбрать причину. Писать длинные объяснения не нужно.</p><p>Наблюдения желательно добавить, если есть важное замечание. Можно оставить поле пустым.</p><div class="row"><button onclick="showDoc(\'codebook\')">Полный кодбук</button><button onclick="folder(false)">Мои сохранения</button></div>')}
const originalInitForGuided=init;
init=async function(){await originalInitForGuided();if(S){ui.exercise=Math.min(S.training.exerciseIndex||0,exercises().length-1);render()}};

const renderGuidedWeb=render;
render=function(){renderGuidedWeb();let labels=['1. Начнём здесь','2. Разберёмся вместе','3. Попробуйте сами','4. Ваше задание','5. Сохранить итог'];[...$('nav').children].filter(x=>x.tagName==='BUTTON').forEach((x,i)=>x.textContent=labels[i]);document.querySelector('.brand small').textContent='Помощник кодировщика · всё остаётся на компьютере'};
